import sqlite3, random
from lib import *
import lib
subject('sql', 'SQL', 'sql', 'lang', 'Language-specific practice: SELECT and filtering, aggregates and GROUP BY, joins, built-in functions and CASE, subqueries, CTEs and window functions (SQLite).')
NM = ['Asha', 'Ravi', 'Isha', 'Dev', 'Mira', 'Kabir', 'Zoya', 'Neel', 'Tara', 'Omar', 'Lena', 'Vik']
DP = ['HR', 'IT', 'Ops', 'Fin']
CT = ['Pune', 'Delhi', 'Goa', 'Agra']
PN = ['pen', 'book', 'bag', 'lamp', 'desk', 'cup', 'bulb', 'fan']
def q(v): return "'%s'" % v if isinstance(v, str) else ('NULL' if v is None else str(v))
def ins(t, cols, rows): return 'CREATE TABLE %s (%s);\n' % (t, ', '.join(cols)) + ''.join('INSERT INTO %s VALUES (%s);\n' % (t, ', '.join(q(x) for x in r)) for r in rows)
def D_emp(r):
    n = r.randint(5, 9); ns = r.sample(NM, n)
    return ins('emp', ['id INTEGER', 'name TEXT', 'dept TEXT', 'salary INTEGER', 'age INTEGER'], [(i + 1, ns[i], r.choice(DP), r.randint(20, 90) * 1000, r.randint(21, 58)) for i in range(n)])
def D_stu(r):
    n = r.randint(5, 9); ns = r.sample(NM, n)
    return ins('stu', ['id INTEGER', 'name TEXT', 'class INTEGER', 'marks INTEGER'], [(i + 1, ns[i], r.randint(9, 12), r.randint(20, 100)) for i in range(n)])
def D_cust(r):
    n = r.randint(3, 6); ns = r.sample(NM, n)
    return ins('cust', ['id INTEGER', 'name TEXT', 'city TEXT'], [(i + 1, ns[i], r.choice(CT)) for i in range(n)])
def D_ord(r):
    n = r.randint(5, 10); c = r.randint(3, 6)
    return ins('ord', ['id INTEGER', 'cust_id INTEGER', 'amount INTEGER', 'day INTEGER'], [(i + 1, r.randint(1, c + 1), r.randint(1, 50) * 10, r.randint(1, 28)) for i in range(n)])
def D_prod(r):
    n = r.randint(4, 8); ns = r.sample(PN, n)
    return ins('prod', ['id INTEGER', 'name TEXT', 'price INTEGER', 'qty INTEGER'], [(i + 1, ns[i], r.randint(5, 99), r.randint(0, 30)) for i in range(n)])
def D_dept(r): return ins('dept', ['dept TEXT', 'city TEXT'], [(d, r.choice(CT)) for d in DP[:r.randint(2, 4)]])
def D_null(r):
    n = r.randint(5, 8); ns = r.sample(NM, n)
    return ins('emp', ['id INTEGER', 'name TEXT', 'dept TEXT', 'salary INTEGER', 'age INTEGER'], [(i + 1, ns[i], r.choice(DP + [None]), r.choice([None, r.randint(20, 90) * 1000]), r.randint(21, 58)) for i in range(n)])
DS = {'emp': (D_emp, 'emp(id, name, dept, salary, age)'), 'stu': (D_stu, 'stu(id, name, class, marks)'), 'cust': (D_cust, 'cust(id, name, city)'), 'ord': (D_ord, 'ord(id, cust_id, amount, day)'), 'prod': (D_prod, 'prod(id, name, price, qty)'), 'dept': (D_dept, 'dept(dept, city)'), 'null': (D_null, 'emp(id, name, dept, salary, age) -- dept and salary can be NULL')}
def runq(setup, query):
    c = sqlite3.connect(':memory:'); c.executescript(setup)
    rows = c.execute(query).fetchall(); c.close()
    return '\n'.join('|'.join('' if v is None else str(v) for v in r) for r in rows)
def SQ(level, title, task, tabs, query, k=5):
    tabs = tabs.split(); r = random.Random(sum(map(ord, title)) * 7 + len(task))
    tests = []; seen = set(); tries = 0
    while len(tests) < k + 1 and tries < 60:
        tries += 1; setup = ''.join(DS[t][0](r) for t in tabs)
        if setup in seen: continue
        seen.add(setup); out = runq(setup, query)
        tests.append({'in': setup, 'out': out})
    good = [t for t in tests if t['out'].strip()]
    if len(good) >= 3: tests = good[:k + 1]
    schema = '; '.join(DS[t][1] for t in tabs)
    t = lib.CUR['t']; idx = len(t['items']) + 1
    t['items'].append({'id': 'sql-%s-%02d' % (t['id'], idx), 'title': title, 'level': level, 'statement': task + ' Write one SELECT statement. Tables: ' + schema + '.', 'input': 'The tables are created and filled for you before your query runs (shown as the sample input).', 'output': 'The result rows, one per line, columns separated by |. NULL prints as an empty value. Use ORDER BY exactly as asked.', 'samples': tests[:1], 'tests': tests})

